  5054  static const MD_CHAR* MD_ADMONITION_TAGS[] = { _T("note"), _T("tip"), _T("important"), _T("warning"), _T("caution") };
  5055
  5056  static int
  5057  md_process_all_blocks(MD_CTX* ctx)
  5058  {
  5059      int byte_off = 0;
  5060      int ret = 0;
  5061
  5062      /* ctx->containers now is not needed for detection of lists and list items
  5063       * so we reuse it for tracking what lists are loose or tight. We rely
  5064       * on the fact the vector is large enough to hold the deepest nesting
  5065       * level of lists. */
  5066      ctx->n_containers = 0;
  5067
  5068      while(byte_off < ctx->n_block_bytes) {
  5069          MD_BLOCK* block = (MD_BLOCK*)((char*)ctx->block_bytes + byte_off);
  5070          union {
  5071              MD_BLOCK_UL_DETAIL ul;
  5072              MD_BLOCK_OL_DETAIL ol;
  5073              MD_BLOCK_LI_DETAIL li;
  5074              MD_BLOCK_ADMONITION_DETAIL adm;
  5075          } det;
  5076
  5077          switch(block->type) {
  5078              case MD_BLOCK_UL:
  5079                  det.ul.is_tight = (block->flags & MD_BLOCK_LOOSE_LIST) ? FALSE : TRUE;
  5080                  det.ul.mark = (CHAR) block->data;
  5081                  break;
  5082
  5083              case MD_BLOCK_OL:
  5084                  det.ol.start = block->n_lines;
  5085                  det.ol.is_tight = (block->flags & MD_BLOCK_LOOSE_LIST) ? FALSE : TRUE;
  5086                  det.ol.mark_delimiter = (CHAR) block->data;
  5087                  break;
  5088
  5089              case MD_BLOCK_LI:
  5090                  det.li.is_task = (block->data != 0);
  5091                  det.li.task_mark = (CHAR) block->data;
  5092                  det.li.task_mark_offset = (OFF) block->n_lines;
  5093                  break;
  5094
  5095              case MD_BLOCK_ADMONITION:
  5096              {
  5097                  MD_TEXTTYPE adm_substr_types[1] = { MD_TEXT_NORMAL };
  5098                  MD_OFFSET adm_substr_offsets[2];
  5099
  5100                  adm_substr_offsets[0] = 0;
  5101                  adm_substr_offsets[1] = md_strlen(MD_ADMONITION_TAGS[block->data]);
  5102
  5103                  det.adm.type.text = MD_ADMONITION_TAGS[block->data];
  5104                  det.adm.type.size = adm_substr_offsets[1];
  5105                  det.adm.type.substr_types = adm_substr_types;
  5106                  det.adm.type.substr_offsets = adm_substr_offsets;
  5107                  break;
  5108              }
  5109
  5110              default:
  5111                  /* noop */
  5112                  break;
  5113          }
  5114
  5115          if(block->flags & MD_BLOCK_CONTAINER) {
  5116              if(block->flags & MD_BLOCK_CONTAINER_CLOSER) {
  5117                  MD_LEAVE_BLOCK(block->type, &det);
  5118
  5119                  if(block->type == MD_BLOCK_UL || block->type == MD_BLOCK_OL ||
  5120                     block->type == MD_BLOCK_QUOTE || block->type == MD_BLOCK_ADMONITION)
  5121                      ctx->n_containers--;
  5122              }
  5123
  5124              if(block->flags & MD_BLOCK_CONTAINER_OPENER) {
  5125                  MD_ENTER_BLOCK(block->type, &det);
  5126
  5127                  if(block->type == MD_BLOCK_UL || block->type == MD_BLOCK_OL) {
  5128                      ctx->containers[ctx->n_containers].is_loose = (block->flags & MD_BLOCK_LOOSE_LIST) ? TRUE : FALSE;
  5129                      ctx->n_containers++;
  5130                  } else if(block->type == MD_BLOCK_QUOTE  ||  block->type == MD_BLOCK_ADMONITION) {
  5131                      /* This causes that any text in a block quote, even if
  5132                       * nested inside a tight list item, is wrapped with
  5133                       * <p>...</p>. */
  5134                      ctx->containers[ctx->n_containers].is_loose = TRUE;
  5135                      ctx->n_containers++;
  5136                  }
  5137              }
  5138          } else {
  5139              MD_CHECK(md_process_leaf_block(ctx, block));
  5140
  5141              if(block->type == MD_BLOCK_CODE || block->type == MD_BLOCK_HTML)
  5142                  byte_off += block->n_lines * sizeof(MD_VERBATIMLINE);
  5143              else
  5144                  byte_off += block->n_lines * sizeof(MD_LINE);
  5145          }
  5146
  5147          byte_off += sizeof(MD_BLOCK);
  5148      }
  5149
  5150      ctx->n_block_bytes = 0;
  5151
  5152  abort:
  5153      return ret;
  5154  }
